 async function source(){click(`[data-track="${track.id}"]`);click(button('load'));await until(()=>primary.track===track&&!primary.processing,'Warped primary Load');input('[data-tempo="1"]',0);click(button('sync'));await until(()=>primary.sync&&primary.syncState==='armed','Primary armed at120');input('[data-tempo="1"]',5);await until(()=>Math.abs(primary.rate-1.05)<1e-10&&!primary.processing,'Primary common126');click('[data-deck="1"][data-action="tab"][data-tab="Loops"]');click('[data-deck="1"][data-action="pad"][data-pad="1"]');await until(()=>primary.loop&&Math.abs(primary.loopOut-47/15)<1e-8&&!primary.processing,'Warped primary savedloop');click(button('play'));await until(()=>primary.playing&&!primary.processing&&engine.voices.get(1)?.warpLoopTransport&&engine.ctx.currentTime>primary.anchorTime+.05,'Warped primary playing');}
