   const row={name,prePCM:await capture(.3),clocks:[]};r.stages.push(row);await until(()=>{const p=engine.position(primary);return p>=from&&p<to;},'Declared primary source interval');row.before=snapshot();currentRow=row;click('[data-deck="0"][data-action="sync"]');await until(()=>row.futureProbe&&!d.processing&&!d.playQueued,'Actual Sync attempt settled');await until(()=>engine.ctx.currentTime>row.futureProbe.when+.15,'Future attempt audio window');row.after=snapshot();row.referenceHashes=await Promise.all([0,1].map(c=>sha(engine.voices.get(0).sources[0].buffer.getChannelData(c).buffer)));const timer=setInterval(()=>row.clocks.push(snapshot()),20);try{row.pcm=await capture(3);}finally{clearInterval(timer);}row.last=snapshot();currentRow=null;
